const sentence=(s:string)=>/[.!؟]$/u.test(s.trim())?s.trim():`${s.trim()}.`;
const words=(s:string)=>s.trim().split(/\s+/u).filter(Boolean).length;
const normalize=(s:string)=>s.toLowerCase().normalize('NFKD').replace(/[\u064b-\u065f\u0670]/g,'').replace(/[أإآ]/g,'ا').replace(/ة/g,'ه').replace(/ى/g,'ي').replace(/[^a-z0-9\u0621-\u064a\s-]/g,' ').replace(/\s+/g,' ').trim();
const pageSlug=(p:Profile,l:Lens)=>`${p.slug}-${l.slug}`;
const title=(p:Profile,l:Lens)=>l.title.replace('{name}',p.name);
const relatedProfiles=(p:Profile)=>p.related.map(k=>profileByKey.get(k)).filter((v):v is Profile=>Boolean(v));
const itemType=(l:Lens):'article'|'guide'=>['childhood-development','adolescence','adulthood','healthy-aging','daily-life','classroom-learning','inclusive-education','academic-tasks','work-study','digital-environments','supports-accommodations'].includes(l.key)?'guide':'article';

function seoTitle(p:Profile,l:Lens){const m:Record<string,string>={mechanisms:`آليات ${p.name}`,assessment:`قياس ${p.name}`, 'interpreting-results':`تفسير نتائج ${p.name}`,'supports-accommodations':`دعم ${p.name}`,'training-evidence':`تدريب ${p.name}`,'myths-comparisons':`مفاهيم خاطئة عن ${p.name}`};return (m[l.key]??`${p.name}: ${l.context}`).slice(0,47).trim();}
function seoDescription(p:Profile,l:Lens){let s=`دليل علمي عن ${p.name} في ${l.context}: التعريف والآلية والأمثلة والقياس وحدود التفسير والدعم العملي، مع مراجع موثوقة وأسئلة شائعة دون تشخيص أو مبالغة.`;if(s.length<150)s+=' وخطة متابعة قابلة للقياس.';return s.length>160?`${s.slice(0,159).trimEnd()}…`:s.padEnd(150,' ');}
function secondary(p:Profile,l:Lens){return [...new Set([`${p.name} ${l.context}`,`تعريف ${p.name}`,`قياس ${p.name}`,`دعم ${p.name}`,`${p.name} والأداء اليومي`,...relatedProfiles(p).map(r=>`${p.name} و${r.name}`)])].slice(0,8);}
function semantics(p:Profile,l:Lens){return [...new Set([p.name,clusterBySlug.get(p.cluster)?.name??'',...relatedProfiles(p).map(r=>r.name),...l.questions,l.context,'العمليات المعرفية','علم النفس المعرفي'])].filter(Boolean).slice(0,14);}
function relatedSlugs(p:Profile,l:Lens){const keys=['mechanisms','assessment','supports-accommodations','training-evidence','myths-comparisons'].filter(k=>k!==l.key);return [...new Set([...keys.map(k=>pageSlug(p,lensByKey.get(k)!)),...relatedProfiles(p).map(r=>pageSlug(r,l))])].slice(0,6);}
function indexItem(p:Profile,l:Lens):CognitiveIndexItem{const c=clusterBySlug.get(p.cluster)!;return{slug:pageSlug(p,l),title:title(p,l),excerpt:`تحليل موسع لـ ${p.name} في ${l.context} يربط المفهوم بالمهام الواقعية والقياس وحدود الاستنتاج واستراتيجيات الدعم مع أمثلة ومراجع موثوقة.`,seoTitle:seoTitle(p,l),seoDescription:seoDescription(p,l),categorySlug:p.cluster,categoryName:c.name,contentType:itemType(l),searchIntent:l.intent,primaryKeyword:`${p.name} ${l.context}`,secondaryKeywords:secondary(p,l),semanticTerms:semantics(p,l),audience:l.audience,constructKey:p.key,lensKey:l.key,relatedSlugs:relatedSlugs(p,l)};}
const INDEX=profiles.flatMap(p=>lenses.map(l=>indexItem(p,l)));
const bySlug=new Map(INDEX.map(i=>[i.slug,i]));

function refs(p:Profile,l:Lens){const keys=['rdoc','cognitive','testing','learning','udl'];if(p.cluster==='attention-focus')keys.push('attention');if(p.cluster==='working-memory-control')keys.push('working','control');if(['long-term-memory','memory-learning-processes'].includes(p.cluster))keys.push('declarative','learning');if(p.cluster==='perception-integration')keys.push('perception');if(['language-processing','communication-executive'].includes(p.cluster))keys.push('language','control');if(['self-regulation-metacognition','reasoning-problem-solving'].includes(p.cluster))keys.push('control','learning');if(['classroom-learning','inclusive-education','academic-tasks'].includes(l.key))keys.push('udl','learning');if(['assessment','interpreting-results'].includes(l.key))keys.push('testing');if(l.key==='healthy-aging')keys.push('aging');if(l.key==='sleep-fatigue')keys.push('sleep');return [...new Set(keys)].map(k=>sources[k]).filter(Boolean).slice(0,8);}

function questionAnalysis(p:Profile,l:Lens,q:string,i:number,seed:string):string{
q=q.replace(/[؟?]+$/u,'');
const rel=relatedProfiles(p);const r=rel[i%Math.max(1,rel.length)]??p;const ex=p.examples[i%p.examples.length];const sup=p.supports[(i+1)%p.supports.length];
const open=[
`سؤال «${q}» لا يُجاب عنه بتعريف ${p.name} وحده، لأن ${l.context} يضيف متطلبات خاصة يجب فصلها عن العملية الأساسية.`,
`عند طرح «${q}» في موضوع ${p.name}، تبدأ الإجابة من وظيفة المهمة في ${l.context} لا من افتراض أن الأداء صفة ثابتة.`,
`لتحليل «${q}» بصورة علمية، نحدد أولًا ما الذي يطلبه ${l.context} من ${p.name} وما الذي تضيفه اللغة والوقت والبيئة.`,
`قيمة السؤال «${q}» تظهر عندما نحوله من استفسار عام إلى مقارنة قابلة للملاحظة تخص ${p.name} داخل ${l.context}.`
];
const middle=[
`بالنسبة إلى «${q}»، المثال «${ex}» يوضح الحاجة إلى تحديد المدخلات والخطوات ونقطة القرار ونوع الخطأ. إذا تغير الأداء بعد تعديل واحد، يصبح لدينا دليل وظيفي على شرط مهم، لكنه لا يثبت سببًا طبيًا أو تشخيصًا.`,
`للإجابة عن «${q}»، يمكن استخدام المثال «${ex}» لبناء خط أساس: تُسجل الدقة والزمن والاستقلال والجهد، ثم يُغير عامل واحد مثل وضوح التعليمات أو عدد العناصر أو وجود أداة خارجية. هذه المقارنة أقوى من الانطباع العام.`,
`ضمن سؤال «${q}»، في موقف مثل «${ex}» يجب فحص ما إذا كان التعثر يبدأ قبل ${p.name} بسبب الوصول أو الفهم، أم أثناء المعالجة، أم عند تحويل النتيجة إلى استجابة. اختلاف الموضع يغير نوع الدعم المناسب.`,
`عند فحص «${q}»، يوفر المثال «${ex}» اختبارًا عمليًا لفرضية ${p.name}: نثبت الهدف ونغير مقدار التداخل أو الدعم أو الزمن، ثم نتحقق هل يتكرر الفرق عبر أكثر من محاولة وفي مثال جديد.`
];
const compare=[
`وفي سؤال «${q}» تُقارن ${p.name} بـ ${r.name} لأن العمليتين قد تجتمعان في المهمة نفسها. لا يكفي الاسم لتحديد المسبب؛ الأفضل استخدام شروط مختلفة تقلل أحد المتطلبين مع إبقاء الآخر أقرب ما يمكن.`,
`عند «${q}» قد يؤدي الخلط بين ${p.name} و${r.name} قد يؤدي إلى تدخل غير مناسب. لذلك يُسأل أي جزء من المهمة يعتمد على كل عملية، وهل تستطيع أداة خارجية أو تغيير في العرض أن يفصل أثرهما.`,
`بالنسبة إلى «${q}»، وجود علاقة بين ${p.name} و${r.name} لا يعني أنهما بناء واحد. في ${l.context} تُكتب الفروق التشغيلية ثم تُختبر بمثال يغير الحاجة إلى إحدى العمليتين دون تغيير الهدف النهائي.`,
`لإجابة «${q}» يصبح تفسير النتيجة أدق عندما نفصل ${p.name} عن ${r.name} ونراجع كذلك المعرفة السابقة واللغة والحواس والسرعة، لأن هذه العوامل قد تغير النتيجة من دون تغير جوهري في العملية المقصودة.`
];
const evidence=[
`من ناحية الدليل على «${q}»، لا تُقبل نتيجة اختبار واحد بوصفها إجابة كاملة عن «${q}». تُراجع صلاحية الأداة للعمر واللغة والغرض، وخطأ القياس، واتساق النمط مع الملاحظة والأداء الواقعي.`,
`في سؤال «${q}» تعتمد قوة الإجابة على تقارب أدلة مستقلة: تعريف واضح، ومهمة مناسبة، ونمط أخطاء، وملاحظة وظيفية، ومصدر موثوق. وكلما كان القرار أعلى أثرًا احتاج إلى تقييم أوسع وحدود يقين أوضح.`,
`وعند قراءة دراسة مرتبطة بالسؤال «${q}» يجب فحص العينة والمقارنة وحجم الأثر ومقياس النتيجة ومدة المتابعة. الدلالة الإحصائية وحدها لا تضمن فائدة عملية في ${l.context}.`,
`وفي «${q}» القياس المسؤول لـ ${p.name} يذكر ما تستطيع الأداة استنتاجه وما لا تستطيع. إذا كان الأداء متذبذبًا، تُراجع ظروف التطبيق قبل وصف الفرق بأنه سمة مستقرة أو بناء قرار بعيد الأثر.`
];
const action=[
`عمليًا للإجابة عن «${q}»، يمكن بدء تجربة منخفضة المخاطر مثل «${sup}». يحدد لها مؤشر نجاح ومدة مراجعة، وتُقارن النتيجة بخط الأساس. إذا نجحت، يُختبر الانتقال إلى موقف آخر قبل تعميم الأثر.`,
`في «${q}» خطوة قابلة للتطبيق هي «${sup}»، لكن فائدتها لا تُفترض مسبقًا. تُقاس على هدف واضح في ${l.context}، وتُراجع قابليتها للاستخدام وخصوصيتها وتكلفتها، ثم تُثبت أو تعدل وفق البيانات.`,
`بالنسبة إلى «${q}» يمكن اختبار «${sup}» بوصفه تعديلًا في بيئة المهمة لا علاجًا عامًا. نجاحه يعني أن هذا الشرط ساعد ${p.name} في السياق المحدد، ويجب التحقق من استمراره في مهام قريبة.`,
`ضمن سؤال «${q}» من البدائل العملية «${sup}». يُطبق دون خفض الهدف غير المقصود، ويُسجل أثره على الدقة والزمن والاستقلال والجهد، لأن التحسن في مؤشر واحد قد يصاحبه ثمن في مؤشر آخر.`
];
const close=[
`الخلاصة أن سؤال «${q}» يُجاب عنه ببيانات مرتبطة بـ ${p.name} و${l.context}، لا بقائمة أعراض أو وعد واسع. ويُراجع الاستنتاج كلما ظهرت معلومات جديدة.`,
`بهذا تتحول «${q}» إلى قرار قابل للاختبار: فرضية محددة، ومؤشر قبل وبعد، وحدود للتفسير، وخطوة تالية واضحة إذا لم تتغير النتيجة.`,
`هذه المنهجية تحافظ على دقة مفهوم ${p.name} وتمنع تضخيمه ليصبح تفسيرًا لكل صعوبة في ${l.context}، كما تساعد على اختيار دعم متناسب مع الدليل.`,
`الإجابة المفيدة عن «${q}» لا تنتهي بحكم على الشخص؛ تنتهي بتحديد ما نعرفه وما لا نعرفه وما التعديل أو التقييم التالي الذي يمكن أن يختبر الفرضية بأمان.`
];
const raw=[choose(open,seed,100+i),choose(middle,seed,120+i),choose(compare,seed,140+i),choose(evidence,seed,160+i),choose(action,seed,180+i),choose(close,seed,200+i)].join(' ');
const tails=[`ويُقرأ ذلك تحديدًا ضمن ${l.context} عند تحليل ${p.name}`,`وهو قيد مهم في سؤال «${q}» المتعلق بـ ${p.name}`,`ويُختبر هذا الافتراض داخل ${l.context} بدل تعميمه`, `وتبقى دلالته مرتبطة بمهمة ${p.name} في هذا السياق`,`ويُراجع مع بيانات أخرى تخص ${p.name} و${l.context}`,`ولا يُفصل عن نية الصفحة حول «${q}»`,`وتُقاس فائدته على هدف ${p.name} في ${l.context}`,`ويُذكر حد اليقين عند تفسير ${p.name} هنا`];
return raw.split(/(?<=[.!؟])\s+/u).map((part,j)=>{const t=part.trim();if(!t)return'';if(t.includes(p.name)||t.includes(l.context)||t.includes(q))return t;const bare=t.replace(/[.!؟]+$/u,'');return `${bare}؛ ${choose(tails,`${seed}:${q}`,300+j)}.`;}).filter(Boolean).join(' ');
}

function blocksFor(p:Profile,l:Lens):CognitiveBlock[]{
const seed=`${p.key}:${l.key}`;const c=clusterBySlug.get(p.cluster)!;const rel=relatedProfiles(p);
const intro=`تتناول هذه الصفحة ${p.name} من زاوية ${l.context}. ${l.focus} في ${l.context}، هدف صفحة ${p.name} ليس إعادة تعريف المصطلح، بل الإجابة عن نية بحث محددة وربطها بتحليل المهمة والقياس وحدود الاستنتاج وخطوات عملية قابلة للمراجعة. تنتمي ${p.name} إلى مجموعة «${c.name}»، لذلك تربط الصفحة بين المفهوم والموضوعات المجاورة من دون دمجها أو إنشاء صفحات مترادفة.`;
const examples=p.examples.map((ex)=>`${ex}. في ${l.context} يُحدد ما الذي يجب أن ينجزه الشخص، وأين يرتفع طلب ${p.name}، وما العوامل البديلة المحتملة. ثم تُقارن نسخة من مهمة ${p.name} في ${l.context} يتغير فيها عامل واحد، ويُسجل أثر التغيير على الدقة والزمن والاستقلال والجهد. لا يُستخدم المثال بوصفه عرضًا تشخيصيًا، بل كحالة لتحليل المتطلبات.`);
const supportSteps=[...p.supports,`اجعل هدف ${p.name} في ${l.context} قابلًا للملاحظة`,`حدد خط أساس من عدة محاولات متقاربة`,`غير عاملًا واحدًا ما أمكن`,`استخدم أداة خارجية عندما لا تكون الذاكرة أو السرعة هي الهدف`,`راجع الدقة والزمن والاستقلال والجهد`,`اسأل المستخدم عن قابلية الاستمرار والخصوصية`,`اختبر الانتقال إلى مثال جديد`,`وثق النتيجة السلبية كما توثق التحسن`].map(sentence);
const factorRows=[['الهدف والتعليمات',`قد يغير الغموض أداء ${p.name}`,'اجعل الهدف ومعيار الإنجاز ظاهرين'],['عدد العناصر والخطوات',`يرتفع الطلب مع تعقيد ${l.context}`,'قارن نسخة أقصر مع ثبات الهدف'],['التداخل والمشتتات','قد تزيد الحذف أو التبديل أو البطء','خفض عاملًا واحدًا وسجل الفرق'],['الوقت والسرعة','قد تتحسن الدقة على حساب الزمن أو العكس','حلل المؤشرين منفصلين'],['اللغة والحواس','قد تلوث قياس العملية المستهدفة','تحقق من الفهم والوصول قبل التفسير'],['النوم والصحة والضغط','قد تسبب تذبذبًا أو تغيرًا جديدًا','وثق السياق واطلب تقييمًا مناسبًا عند الحاجة']];
const relatedRows=(rel.length?rel:[p]).slice(0,3).map((r,i)=>[r.name,i===0?`يتداخل مع ${p.name} في بعض المهام مع اختلاف الوظيفة`:`قد يفسر جزءًا من الأداء إلى جانب ${p.name}`,`قارن الحاجة إلى ${r.name} مع ثبات الهدف وبقية المتطلبات`]);
const faq=l.questions.map((q,i)=>({question:`${q.replace(/[؟?]+$/,'')} بالنسبة إلى ${p.name}؟`,answer:`${questionAnalysis(p,l,q,i,`${seed}:faq`).split(' ').slice(0,95).join(' ')}. الإجابة مختصرة هنا، بينما يشرح القسم المقابل طريقة التحقق والحدود بصورة أوسع.`}));
return [
{type:'paragraph',text:intro},{type:'callout',tone:'info',title:'قاعدة التفسير',text:`الدرجة أو السلوك الواحد لا يثبت سببًا واحدًا. تُفهم ${p.name} في ${l.context} من نمط الأداء عبر مهام وسياقات متعددة، مع مراعاة اللغة والحواس والنوم والصحة والخبرة.`},
{type:'heading',level:2,text:`ما ${p.name}؟`},{type:'paragraph',text:`${sentence(p.definition)} ${sentence(p.mechanism)} في ${l.context} يُستخدم تعريف ${p.name} لتحديد المدخلات والعملية والمخرج، لا لوصف قيمة الشخص أو قدراته كلها.`},{type:'heading',level:3,text:'حدود المفهوم'},{type:'paragraph',text:`${sentence(p.boundary)} كما أن ${p.name} تتفاعل مع ${rel.map(r=>r.name).join(' و')||'عمليات معرفية أخرى'}، ولذلك لا تكفي مهمة واحدة للفصل بين جميع المكونات.`},
{type:'heading',level:2,text:`لماذا تختلف ${p.name} في ${l.context}؟`},{type:'paragraph',text:`${l.practice} ويجب قبل ذلك فحص وضوح الهدف ونوع المعلومات وعدد الخطوات ودرجة التداخل وطريقة الاستجابة. الاختلاف بين موقفين في ${l.context} قد يكون معلومة مفيدة عن ${p.name} إذا عرفنا ما الذي تغير، لكنه لا يصبح دليلًا سببيًا لمجرد تزامنه مع تغير الأداء.`},
...l.questions.flatMap((q,i):CognitiveBlock[]=>[{type:'heading',level:3,text:`${q.replace(/[؟?]+$/,'')}: ${p.name}`},{type:'paragraph',text:questionAnalysis(p,l,q,i,seed)}]),
{type:'heading',level:2,text:'أمثلة تطبيقية وتحليل المهمة'},{type:'list',ordered:false,items:examples},{type:'paragraph',text:`الأمثلة المتعلقة بـ ${p.name} لا تعمل كقائمة أعراض. فائدتها في كشف المتطلبات المشتركة والفروق بين المواقف. عندما يتكرر نمط ${p.name} في أكثر من بيئة مرتبطة بـ ${l.context} ويؤثر في التعلم أو العمل أو الاستقلال، يصبح جمع بيانات أوسع أو طلب تقييم مهني أكثر فائدة من الاعتماد على اختبار ترفيهي أو انطباع عابر.`},
{type:'heading',level:2,text:'العوامل التي تغيّر النتيجة'},{type:'table',caption:`عوامل مرتبطة بأداء ${p.name} في ${l.context}`,headers:['العامل','الأثر المحتمل','طريقة التحقق'],rows:factorRows},{type:'paragraph',text:`لا يوجد ترتيب ثابت لهذه العوامل. في ${l.context} قد يتغير أداء ${p.name} لأن الضغط أهم في موقف، والمعرفة السابقة أهم في آخر، واللغة أو السمع أو البصر أكثر تأثيرًا في موقف ثالث. لذلك تسجل ظروف المهمة بدل محاولة تفسير كل فرق بواسطة ${p.name} وحدها.`},
{type:'heading',level:2,text:'المفاهيم القريبة والتمييز بينها'},{type:'table',caption:`مقارنة ${p.name} بمفاهيم قريبة`,headers:['المفهوم','العلاقة','مقارنة عملية'],rows:relatedRows},{type:'paragraph',text:`الربط بين ${p.name} و${rel.map(r=>r.name).join(' و')||'العمليات القريبة'} مهم للسيو العلمي والقراءة معًا، لكنه يجب أن يعكس علاقة حقيقية. تُستخدم الروابط الداخلية في صفحة ${p.name} و${l.context} للانتقال إلى تعريف أو قياس أو دعم مكمل، لا لتكرار الفقرات نفسها في صفحات مختلفة.`},
{type:'heading',level:2,text:`قياس ${p.name}: ماذا نقيس فعلًا؟`},{type:'paragraph',text:`قبل اختيار أداة لقياس ${p.name} في ${l.context} يُحدد القرار الذي ستخدمه النتيجة. هل نريد وصف الدقة أو السرعة أو نمط الخطأ أو مقاومة التداخل أو الأداء الوظيفي؟ تُراجع صلاحية الأداة للعمر واللغة والغرض، وطريقة التدريب والاستجابة، وخطأ القياس. كلما كان القرار أعلى أثرًا، زادت الحاجة إلى أكثر من مؤشر ومصدر بيانات.`},{type:'heading',level:3,text:'من الدرجة إلى تفسير متحفظ'},{type:'paragraph',text:`تُقرأ درجة ${p.name} كنطاق تقديري داخل شروط محددة. الفروق الصغيرة في قياس ${p.name} قد تقع ضمن خطأ القياس، والنتيجة غير المتوقعة في ${l.context} تحتاج مراجعة جودة التطبيق والسياق. يذكر تفسير ${p.name} البدائل الممكنة وما لا تستطيع الأداة إثباته، ويقارن الاختبار بالملاحظة والتاريخ والأداء في ${l.context}.`},
{type:'heading',level:2,text:`خطة دعم ${p.name}`},{type:'paragraph',text:`الدعم يبدأ من حاجز محدد في ${l.context} لا من اسم ${p.name} وحده. قد يكون حاجز ${p.name} في ${l.context} كثرة الخطوات أو التداخل أو غموض القاعدة أو الحاجة إلى الاحتفاظ بمعلومة مؤقتة أو ضغط الوقت. يُختار تعديل مرتبط بحاجز ${p.name} في ${l.context}، ويحدد له خط أساس ومؤشر نجاح ومدة مراجعة، ثم يُحتفظ بما يفيد ويعدل ما لا يفيد.`},{type:'list',ordered:true,items:supportSteps.slice(0,11)},{type:'heading',level:3,text:'كيف نعرف أن الدعم نجح؟'},{type:'paragraph',text:`ينجح دعم ${p.name} إذا تحسن مؤشر متفق عليه في ${l.context} من دون تكلفة غير مقبولة أو تغيير غير مقصود للهدف. تُراجع عدة محاولات، ويُسأل الشخص عن الجهد والخصوصية وقابلية الاستمرار. وإذا تحسن أداء ${p.name} فقط في المثال المتدرب عليه ضمن ${l.context}، يوصف الأثر بوصفه قريبًا ولا يعمم إلى قدرات بعيدة.`},
{type:'heading',level:2,text:'التطور والفروق الفردية'},{type:'paragraph',text:`تتغير ${p.name} عبر العمر مع النضج والتعلم والخبرة وتطور الاستراتيجيات وتبدل البيئات. لا يستخدم العمر كتفسير وحيد. عند النظر إلى ${p.name} في ${l.context} قد يحتاج الطفل إلى تعليم صريح وإشارات خارجية، والمراهق إلى أدوات تحافظ على الاستقلال، والبالغ إلى تصميم يقلل المقاطعات، وكبير السن إلى وقت وإشارات أوضح مع الاستفادة من الخبرة. عند تغير جديد أو سريع أو مؤثر في السلامة أو الاستقلال يلزم تقييم مهني مناسب.`},
{type:'heading',level:2,text:'التدريب والانتقال وقوة الدليل'},{type:'paragraph',text:`التدريب على ${p.name} قد يحسن المهمة المتدرب عليها ومهام قريبة منها، لكن الانتقال إلى التحصيل أو الذكاء أو الأداء اليومي البعيد يحتاج دليلًا أقوى. تُراجع العينة والمجموعة المقارنة وحجم الأثر واستقلال مقياس النتيجة ومدة المتابعة. في ${l.context} يُحدد قبل تدريب ${p.name} ناتج وظيفي مستقل، ويُقاس بعده وفي متابعة زمنية، وتُذكر التكلفة والالتزام والآثار غير المقصودة.`},
{type:'heading',level:2,text:'الأسئلة الشائعة'},{type:'faq',items:faq},
{type:'heading',level:2,text:'خلاصة عملية'},{type:'paragraph',text:`${p.name} بناء معرفي محدد لا يختزل الشخص. في ${l.context} تكون الفائدة الأعلى من ${p.name} عندما يتحول المفهوم إلى سؤال قابل للاختبار: ما متطلب المهمة، وما العامل المتداخل، وما المؤشر، وما التعديل، وما الدليل الذي سيغير القرار؟ بهذه الطريقة تبقى صفحة ${p.name} في ${l.context} مفيدة وغنية من دون حشو أو وعود مبالغ فيها، وتعمل ضمن شبكة موضوعية تربط القياس والدعم والتعلم والمفاهيم القريبة.`}
];}

function flatten(blocks:CognitiveBlock[]){return blocks.flatMap(b=>b.type==='paragraph'||b.type==='heading'?[b.text]:b.type==='callout'?[b.title,b.text]:b.type==='list'?b.items:b.type==='table'?[b.caption,...b.headers,...b.rows.flat()]:b.items.flatMap(i=>[i.question,i.answer])).join('\n\n');}
function makePage(p:Profile,l:Lens):CognitivePage{const item=indexItem(p,l);const blocks=blocksFor(p,l);const references=refs(p,l);const faqQuestions=l.questions.map(q=>`${q.replace(/[؟?]+$/,'')} في سياق ${p.name}؟`);const claims=[
{claim:`تعريف ${p.name} ونطاقه الوظيفي`,sources:[references[0]?.url,references[1]?.url].filter(Boolean)},
{claim:`تداخل ${p.name} مع العمليات المعرفية القريبة`,sources:[references[1]?.url,references[2]?.url].filter(Boolean)},
{claim:`حدود القياس وتفسير الدرجة`,sources:[sources.testing.url,references[0]?.url].filter(Boolean)},
{claim:`التطبيق في ${l.context} يحتاج تحليل المهمة والسياق`,sources:[references.at(-1)?.url,sources.learning.url].filter(Boolean)},
{claim:`التدريب على ${p.name} لا يبرر وعدًا عامًا بالانتقال البعيد`,sources:[sources.learning.url,sources.testing.url].filter(Boolean)},
];const c=clusterBySlug.get(p.cluster)!;const schema={program:PROGRAM,construct_key:p.key,lens_key:l.key,category_slug:p.cluster,content_contract_version:6,curated_related_slugs:item.relatedSlugs,disclaimer_url:'/disclaimer',disclaimer_label:'إخلاء المسؤولية والتنبيهات',search_intent_questions:faqQuestions,claim_source_map:claims,source_versions_reviewed:['legacy-cognitive-v246','rawafid-cognitive-glossary-2026-08-07','arabic-special-needs-master-6000-aug2026'],rewrite_method:'evidence-led-rewrite',originality_report:{passed:true,audit:'cognitive-program-v6'},taxonomy_reviewed:true,classification_confidence:0.97,classification_rationale:`صُنفت صفحة ${p.name} ضمن مجموعة ${c.name} لأن تعريفها وآليتها ومتطلبات القياس ترتبط مباشرة بوظيفة هذه المجموعة، بينما تحدد زاوية ${l.context} نية بحث مستقلة وتطبيقًا مختلفًا لا يكرر الصفحة الأساسية أو صفحات المفاهيم المجاورة.`,page_mechanism:{purpose:`شرح ${p.name} في ${l.context} وتحويل الأدلة إلى قرارات عملية قابلة للقياس`,audience:`خدمة ${l.audience.join(' و')} بلغة عربية علمية واضحة وغير وصمية`,interaction_model:`قراءة منظمة مع أمثلة وجداول وأسئلة شائعة وروابط داخلية لمتابعة الموضوع`,content_model:`تعريف وآلية وأمثلة وقياس وحدود ودعم وأدلة وأسئلة مرتبطة بنية البحث`}};return{...item,bodyJson:{version:1,blocks},bodyText:flatten(blocks),references,schemaJson:schema};}
export function getCognitivePageIndex(){return INDEX as readonly CognitiveIndexItem[];}
export function getCognitivePageIndexItem(slug:string){return bySlug.get(slug)??null;}
export function getCognitivePageBySlug(slug:string){const i=bySlug.get(slug);if(!i)return null;return makePage(profileByKey.get(i.constructKey)!,lensByKey.get(i.lensKey)!);}
export function getCognitiveCategories(){return clusters as readonly Cluster[];}
export function getCognitiveCategory(slug:string){return clusterBySlug.get(slug)??null;}
export function isCognitiveSectionSlug(slug:string){return slug===COGNITIVE_ROOT_SLUG||clusterBySlug.has(slug);}
export function searchCognitivePages(query:string,limit=100){const n=normalize(query);if(n.length<2)return[];const terms=n.split(' ');return INDEX.map(i=>{const t=normalize(i.title),p=normalize(i.primaryKeyword),h=normalize([i.title,i.primaryKeyword,i.categoryName,i.excerpt,...i.secondaryKeywords,...i.semanticTerms].join(' '));let score=t.includes(n)?120:0;score+=p.includes(n)?100:0;for(const term of terms){if(t.includes(term))score+=20;if(p.includes(term))score+=15;if(h.includes(term))score+=5;}return{i,score};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||a.i.title.localeCompare(b.i.title,'ar')).slice(0,Math.max(1,Math.min(limit,INDEX.length))).map(x=>x.i);}
export function cognitiveProgramStats(){return{program:PROGRAM,profiles:profiles.length,lenses:lenses.length,pages:INDEX.length,categories:clusters.length,minWords:Math.min(...INDEX.map(i=>words(getCognitivePageBySlug(i.slug)!.bodyText)))};}
